mapper.select:
SELECT session_id, user_id, state::text AS state, turn_count
FROM flow_session
WHERE session_id = #{sessionId}

mapper.update:
UPDATE flow_session
SET state = CAST(#{stateJson} AS jsonb), turn_count = #{turnCount}, updated_at = now()
WHERE session_id = #{sessionId}

mapper.select:
SELECT id, turn_id, role, content
FROM flow_message
WHERE session_id = #{sessionId} AND id > #{afterId}
ORDER BY id DESC
LIMIT #{limit}

SELECT role, content
FROM flow_message
WHERE session_id = #{sessionId}
ORDER BY id DESC
LIMIT #{limit}
